# area: abstract_classes
# hypothesis: static checkers reject instantiating a class that leaves an abstract property or method unimplemented, and do not count ABC.register() virtual subclasses as implementing the ABC.
import abc
from typing import reveal_type


class Shape(abc.ABC):
    @property
    @abc.abstractmethod
    def sides(self) -> int:
        raise NotImplementedError

    @abc.abstractmethod
    def area(self) -> float:
        raise NotImplementedError

    def describe(self) -> str:
        return f'{self.sides} sides, area {self.area():.1f}'


class Square(Shape):
    def __init__(self, side: float) -> None:
        self.side = side

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self.side * self.side


class HalfDone(Shape):
    def area(self) -> float:
        return 0.0


class Triangle:
    @property
    def sides(self) -> int:
        return 3

    def area(self) -> float:
        return 0.5


Shape.register(Triangle)
sq = Square(2.0)
reveal_type(sq.sides)
print(sq.describe())
print(isinstance(Triangle(), Shape))
tri: Shape = Triangle()  # expect-error: Triangle is not a nominal subclass
print(tri.area())


def make_blob() -> Shape:
    return HalfDone()  # expect-error: HalfDone leaves abstract 'sides' unimplemented


try:
    make_blob()
except TypeError as exc:
    print('runtime:', type(exc).__name__)
